async function mbCouponUse (id) { const d = await mbPost({ op: 'couponuse', couponId: id, reqId: mbReq() }); if (!d || !d.ok) return mbToast((d && d.error) || '核銷失敗', true); mbToast('已核銷：' + d.name); if (_mbCur) mbOpen(_mbCur.member.id) }
