async function mbCampStatus (id, st) { const d = await mbPost({ op: 'campaignstatus', id, status: st }); if (!d || !d.ok) return mbToast((d && d.error) || '失敗', true); mbToast('已更新'); mbCamp() }
async function mbCampStats (id) { const d = await mbGet('op=campaign&id=' + id); if (!d || !d.ok) return mbToast((d && d.error) || '讀不到', true); const c = d.campaign; mbModal(`<h3 style="margin:0 0 6px">${mbEsc(c.name)} 抽獎紀錄</h3><div class="hint">剩 ${c.free}/${c.total} 槽・${(c.prizes || []).map(p => `${mbEsc(p.name)} ${p.left}/${p.total}`).join('・')}</div><div style="margin-top:8px;max-height:60vh;overflow:auto;font-size:13px">${(d.draws || []).map(x => `<div style="display:flex;justify-content:space-between;gap:8px;border-bottom:1px dashed var(--line);padding:4px 0"><span>${mbEsc(x.member.name || '')} <span class="hint">${mbEsc(x.member.mno || '')}</span></span><span>${mbEsc((x.prize || {}).name || '')}${(x.prize || {}).capped ? ' <span class="hint">(上限)</span>' : ''}</span><span class="hint">${mbT(x.created_at)}</span></div>`).join('') || '<span class="hint">還沒人抽</span>'}</div><div style="text-align:right;margin-top:10px"><button class="mini" onclick="mbCamp()">返回</button></div>`, 560) }
