const MB_SEG = { all: '全部會員', active30: '近 30 天有消費', sleep30: '有消費但 30 天沒來', never: '還沒消費過', pts: '有可用點數' }
async function mbPush () {
  const seg = 'all'
  const d = await mbGet('op=pushpreview&segment=' + seg); if (!d || !d.ok) return mbToast((d && d.error) || '讀不到', true)
  const q = d.quota || {}
  mbModal(`<h3 style="margin:0 0 6px">推播給會員（GROUN:D 官方帳號）</h3><div class="hint">推播按人頭扣官方帳號額度；排除退會、停用、勾「不收行銷訊息」的人。先「測試發給我」看效果再正式發。</div>
    <div style="display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:10px;align-items:end"><label class="hint">對象 <select id="mbU_seg" onchange="mbPushPreview()" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:8px;background:var(--card);color:inherit">${Object.entries(MB_SEG).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select></label><div id="mbU_n" style="font-weight:800;padding-bottom:8px">${d.n} 人${q.used != null ? `・本月額度已用 ${q.used}${q.limit != null ? ' / ' + q.limit : ''}` : ''}</div></div>
    <textarea id="mbU_text" rows="5" placeholder="訊息內容" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:8px;background:var(--card);color:inherit;font-family:inherit;font-size:14px;margin-top:8px"></textarea>
    <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px"><button class="mini" onclick="mbClose()">取消</button><button class="mini" onclick="mbPushGo(true)">測試發給我</button><button class="mini on" onclick="mbPushGo(false)">正式發送</button></div>
    <details style="margin-top:10px"><summary class="hint">發送紀錄</summary>${(d.log || []).map(l => `<div class="hint" style="font-size:12px;padding:3px 0;border-bottom:1px dashed var(--line)">${mbT(l.t)} ${mbEsc(l.by)}・${MB_SEG[l.segment] || l.segment}・${l.sent}/${l.n} 成功${l.fail ? '・' + l.fail + ' 失敗' : ''}<br>${mbEsc(l.text)}</div>`).join('') || '<span class="hint">—</span>'}</details>`, 600)
}
async function mbPushPreview () { const seg = (document.getElementById('mbU_seg') || {}).value || 'all'; const d = await mbGet('op=pushpreview&segment=' + seg); const el = document.getElementById('mbU_n'); if (el && d && d.ok) { const q = d.quota || {}; el.textContent = `${d.n} 人${q.used != null ? '・本月額度已用 ' + q.used + (q.limit != null ? ' / ' + q.limit : '') : ''}` } }
async function mbPushGo (test) {
  const seg = (document.getElementById('mbU_seg') || {}).value || 'all', text = (document.getElementById('mbU_text') || {}).value || ''
  if (!text.trim()) return mbToast('先寫內容', true)
  if (!test) { const n = (document.getElementById('mbU_n') || {}).textContent || ''; if (!(await mbConfirm(`確定正式發送給「${MB_SEG[seg]}」${n}？會扣官方帳號額度，送出不能收回。`))) return }
  const d = await mbPost({ op: 'pushsend', segment: seg, text, test }); if (!d || !d.ok) return mbToast((d && d.error) || '發送失敗', true)
  mbToast(test ? '已發到你的 LINE' : `已發送 ${d.sent}/${d.n} 人`); if (!test) mbClose()
}
function mbConfirm (msg) { return new Promise(res => { const ov = document.createElement('div'); ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:99;display:flex;align-items:center;justify-content:center;padding:14px'; ov.innerHTML = `<div style="background:var(--card);border:1.5px solid var(--line);border-radius:14px;padding:16px;width:min(380px,100%)"><div style="font-size:15px;margin-bottom:12px">${mbEsc(msg)}</div><div style="display:flex;gap:8px;justify-content:flex-end"><button class="mini" id="mbC_no">取消</button><button class="mini on" id="mbC_yes">確定</button></div></div>`; document.body.appendChild(ov); ov.querySelector('#mbC_no').onclick = () => { ov.remove(); res(false) }; ov.querySelector('#mbC_yes').onclick = () => { ov.remove(); res(true) } }) }
