  mbModal(`<h3 style="margin:0 0 6px">入點對帳（近 14 天）</h3><div class="hint">「入點金額」是店員／發票／團訂登錄的消費，「POS 實收」是 Wixtar 日結；比例高得奇怪＝有人亂入點。可疑清單：同一會員 10 分內兩筆、超過單筆上限。</div>
    <div style="overflow:auto;margin-top:8px"><table style="border-collapse:collapse;width:100%;font-size:13px"><thead><tr style="text-align:left"><th style="padding:6px;border:1px solid var(--line)">日期</th><th style="padding:6px;border:1px solid var(--line);text-align:right">店員入點</th><th style="padding:6px;border:1px solid var(--line);text-align:right">發票自助</th><th style="padding:6px;border:1px solid var(--line);text-align:right">團訂</th><th style="padding:6px;border:1px solid var(--line);text-align:right">筆數</th><th style="padding:6px;border:1px solid var(--line);text-align:right">POS 實收</th><th style="padding:6px;border:1px solid var(--line);text-align:right">占比</th></tr></thead><tbody>${(d.days || []).map(r => `<tr><td style="padding:6px;border:1px solid var(--line)">${r.date}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${mbN(r.staff)}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${mbN(r.inv)}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${mbN(r.grp)}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${r.n}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${r.pos ? mbN(r.pos) : '<span class="hint">—</span>'}</td><td style="padding:6px;border:1px solid var(--line);text-align:right;${r.ratio > 100 ? 'color:var(--red);font-weight:800' : ''}">${r.ratio == null ? '—' : r.ratio + '%'}</td></tr>`).join('') || '<tr><td colspan="7" class="hint" style="padding:10px">近 14 天沒有入點</td></tr>'}</tbody></table></div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px"><div><b style="font-size:13.5px">店員入點排行</b>${(d.staff || []).map(x => `<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0;border-bottom:1px dashed var(--line)"><span>${mbEsc(x.name)}</span><span>${x.n} 筆・${mbN(x.amount)}</span></div>`).join('') || '<div class="hint">—</div>'}</div><div><b style="font-size:13.5px;color:#d97706">可疑</b>${(d.flags || []).map(f => `<div style="font-size:12.5px;padding:3px 0;border-bottom:1px dashed var(--line)">${mbEsc(f.kind)}：${mbEsc(f.member.name || '')} ${mbN(f.amount)}・${mbEsc(f.by || '')}・${mbT(f.at)}</div>`).join('') || '<div class="hint">沒有</div>'}</div></div>
    <div style="text-align:right;margin-top:10px"><button class="mini" onclick="mbClose()">關閉</button></div>`, 760)
