function mbStoreSel (id) { const st = (_mbD.cfg || {}).stores || { gd: { name: 'GROUN:D' } }; const cur = (() => { try { return localStorage.getItem('mbStore') } catch (_) { return '' } })() || 'gd'; return `<select id="${id}" onchange="try{localStorage.setItem('mbStore',this.value)}catch(_){}" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:8px;background:var(--card);color:inherit">${Object.entries(st).filter(([k, v]) => v.active !== false).map(([k, v]) => `<option value="${k}" ${cur === k ? 'selected' : ''}>${mbEsc(v.name)}</option>`).join('')}</select>` }
