async function mbSettle (month) {
  const d = await mbGet('op=settle' + (month ? '&month=' + month : '')); if (!d || !d.ok) return mbToast((d && d.error) || '讀不到', true)
  const prev = (() => { const [y, m] = d.month.split('-').map(Number); const dt = new Date(Date.UTC(y, m - 2, 1)); return dt.toISOString().slice(0, 7) })()
  mbModal(`<div style="display:flex;align-items:center;gap:8px"><h3 style="margin:0">跨店結算 ${d.month}</h3><button class="mini" onclick="mbSettle('${prev}')">‹ 上個月</button><span class="hint">1 點＝${d.pointValue} 元</span></div>
    <div class="hint" style="margin:6px 0">同一個錢包：A 店發的點可能在 B 店被用掉。淨額＝在這家店「被用掉」的價值 − 這家店「發出」的價值；正數＝別家欠它、負數＝它欠別家。要不要真的結，你自己決定。</div>
    <table style="border-collapse:collapse;width:100%;font-size:13px"><thead><tr style="text-align:left"><th style="padding:6px;border:1px solid var(--line)">店</th><th style="padding:6px;border:1px solid var(--line);text-align:right">發出點數</th><th style="padding:6px;border:1px solid var(--line);text-align:right">被用掉點數</th><th style="padding:6px;border:1px solid var(--line);text-align:right">核銷券（張／市值）</th><th style="padding:6px;border:1px solid var(--line);text-align:right">淨額（元）</th></tr></thead><tbody>${(d.stores || []).map(s => `<tr><td style="padding:6px;border:1px solid var(--line);font-weight:800">${mbEsc(s.name)}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${mbN(s.issued)}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${mbN(s.spent)}</td><td style="padding:6px;border:1px solid var(--line);text-align:right">${s.coupons}／${mbN(s.couponValue)}</td><td style="padding:6px;border:1px solid var(--line);text-align:right;font-weight:800;color:${s.net >= 0 ? '#16a34a' : 'var(--red)'}">${s.net >= 0 ? '+' : ''}${mbN(s.net)}</td></tr>`).join('') || '<tr><td colspan="5" class="hint" style="padding:10px">這個月沒有紀錄</td></tr>'}</tbody></table>
    <div style="text-align:right;margin-top:10px"><button class="mini" onclick="mbClose()">關閉</button></div>`, 640)
}
async function mbSurveys () {
  const d = await mbGet('op=surveys&days=30'); if (!d || !d.ok) return mbToast((d && d.error) || '讀不到', true)
  mbModal(`<h3 style="margin:0 0 6px">用餐問卷（近 30 天）${d.avg != null ? `・平均 ${d.avg} 分` : ''}</h3><div style="max-height:65vh;overflow:auto;font-size:13px">${(d.list || []).map(r => `<div style="padding:6px 0;border-bottom:1px dashed var(--line)"><div class="row" style="justify-content:space-between"><b>${mbEsc(r.member.name || '')} <span class="hint">${mbEsc(r.member.mno || '')}</span></b><span style="color:${r.score >= 4 ? '#16a34a' : r.score <= 2 ? 'var(--red)' : '#d97706'};font-weight:900">${'★'.repeat(r.score || 0)}</span></div><div class="hint">${mbT(r.created_at)}${(r.answers || {}).dish ? '・吃了 ' + mbEsc(r.answers.dish) : ''}</div>${(r.answers || {}).comment ? `<div style="margin-top:2px">${mbEsc(r.answers.comment)}</div>` : ''}</div>`).join('') || '<div class="hint">還沒有問卷</div>'}</div><div style="text-align:right;margin-top:10px"><button class="mini" onclick="mbClose()">關閉</button></div>`, 560)
}

async function mbRichMenu () { const b = document.getElementById('mbF_rm'); if (b) { b.disabled = true; b.textContent = '建立中…' } const d = await mbPost({ op: 'richmenu' }); if (!d || !d.ok) { if (b) { b.disabled = false; b.textContent = '掛上圖文選單' } return mbToast((d && d.error) || '失敗', true) } mbToast(`圖文選單已掛上（已切 ${d.linked}／${d.members} 位會員）`); const c = await mbGet('op=cfg'); if (c && c.ok) _mbD.cfg = c.cfg; mbCfg() }
